(() => {
  const $ = (s) => document.querySelector(s);
  const output = $("#output");
  const panelTitle = $("#panelTitle");
  const entries = [
    {en:"Aquilina of Byblos",ar:"القديسة أكويلينا من جبيل",letter:"A",status:"Saint · Martyr",place:"Byblos · جبيل",years:"3rd century",storyEn:"Aquilina is honoured in Christian tradition as a young woman from Byblos who remained faithful to Christ during the persecutions of the Roman Empire. Her witness made her one of the early Christian martyrs associated with the Lebanese coast. The details of her life come through ancient hagiographical tradition.",storyAr:"تكرّم التقاليد المسيحية أكويلينا كشابّة من مدينة جبيل تمسّكت بإيمانها بالمسيح في زمن الاضطهادات الرومانية. وقد جعلت شهادتها منها إحدى الشهيدات المسيحيات الأوائل المرتبطات بالساحل اللبناني. وتَرِد تفاصيل حياتها في المصادر التقليدية القديمة لسِيَر القديسين."},
    {en:"Barbara",ar:"القديسة بربارة",letter:"B",status:"Saint · Martyr",place:"Lebanon · in local tradition",years:"Early Christian tradition",storyEn:"Saint Barbara is widely venerated in Lebanon and across the Eastern Christian world. Christian tradition remembers her as a young woman who held to her faith despite opposition. The historical details of her story vary between traditions, so this account is presented as a tradition rather than a fully documented biography.",storyAr:"تحظى القديسة بربارة بإكرام واسع في لبنان وفي العالم المسيحي الشرقي. وتذكرها التقاليد المسيحية كشابّة تمسّكت بإيمانها رغم المعارضة. تختلف التفاصيل التاريخية لسيرتها بين التقاليد، لذلك تُعرض قصتها هنا بوصفها رواية تقليدية لا سيرة موثّقة بالكامل."},
    {en:"Charbel Makhlouf",ar:"القديس شربل مخلوف",letter:"C",status:"Canonized saint · 1977",place:"Bqaa Kafra & Annaya · بقاعكفرا وعنّايا",years:"1828–1898",storyEn:"Born Youssef Makhlouf in Bqaa Kafra in 1828, Charbel entered the Lebanese Maronite Order and became a monk and priest. He later lived as a hermit at the Monastery of Saints Peter and Paul in Annaya, devoting his life to prayer, silence and the Eucharist. His tomb became a place of pilgrimage, and Pope Paul VI canonized him in 1977.",storyAr:"وُلد يوسف مخلوف في بقاعكفرا سنة 1828. دخل الرهبنة اللبنانية المارونية وصار راهبًا وكاهنًا، ثم عاش ناسكًا في دير القديسين بطرس وبولس في عنّايا، مكرّسًا حياته للصلاة والصمت والقربان المقدّس. أصبح ضريحه مقصدًا للحج، وأعلنه البابا بولس السادس قديسًا سنة 1977."},
    {en:"Estephan El Douaihy",ar:"البطريرك المكرّم إسطفان الدويهي",letter:"E",status:"Venerable · Maronite patriarch",place:"Ehden · إهدن",years:"1630–1704",storyEn:"Born in Ehden in 1630, Estephan El Douaihy became Maronite patriarch and one of the Church's great historians and scholars. He worked to preserve the liturgy, music, manuscripts and memory of the Maronite people through a difficult period. His cause for sainthood has advanced to the recognition of his heroic virtues; he should not be labelled canonized.",storyAr:"وُلد إسطفان الدويهي في إهدن سنة 1630، وأصبح بطريركًا مارونيًا ومن أبرز مؤرّخي الكنيسة وعلمائها. عمل على حفظ الليتورجيا والموسيقى والمخطوطات وذاكرة الشعب الماروني في مرحلة صعبة. وقد أُعلنت بطولته في الفضائل، لذلك لا ينبغي وصفه بأنه قديس مُعلن رسميًا."},
    {en:"Ignatius Maloyan",ar:"الطوباوي إغناطيوس مالويان",letter:"I",status:"Blessed · Martyr",place:"Mardin; formed in Lebanon · ماردين ولبنان",years:"1869–1915",storyEn:"Ignatius Maloyan was an Armenian Catholic archbishop whose priestly formation included study at Bzommar in Lebanon. During the Armenian genocide, he encouraged his people to remain faithful and was killed in 1915. He was beatified by Pope John Paul II in 2001.",storyAr:"كان إغناطيوس مالويان رئيس أساقفة أرمنيًا كاثوليكيًا، وتلقّى تكوينه الكهنوتي في دير بزمار في لبنان. خلال الإبادة الأرمنية، شجّع أبناء رعيته على الثبات في الإيمان، واستشهد سنة 1915. أعلنه البابا يوحنا بولس الثاني طوباويًا سنة 2001."},
    {en:"Nimatullah Al-Hardini",ar:"القديس نعمة الله كسّاب الحرديني",letter:"N",status:"Canonized saint · 2004",place:"Hardine & Kfifan · حردين وكفيفان",years:"1808–1858",storyEn:"Youssef Kassab was born in Hardine in 1808. He joined the Lebanese Maronite Order in 1828, took the name Nimatullah, and became a priest, teacher and spiritual guide at Kfifan. Known for his devotion to the Eucharist and care for his fellow monks, he died in 1858. Pope John Paul II canonized him in 2004.",storyAr:"وُلد يوسف كسّاب في حردين سنة 1808. انضمّ إلى الرهبنة اللبنانية المارونية سنة 1828 واتخذ اسم نعمة الله، وصار كاهنًا ومعلّمًا ومرشدًا روحيًا في كفيفان. عُرف بتعبّده للقربان المقدّس واهتمامه بإخوته الرهبان. توفّي سنة 1858 وأعلنه البابا يوحنا بولس الثاني قديسًا سنة 2004."},
    {en:"Rafqa Pietra Choboq Ar-Rayès",ar:"القديسة رفقا بيطرا الشوبق الريّس",letter:"R",status:"Canonized saint · 2001",place:"Himlaya & Jrabta · حماليا وجربتا",years:"1832–1914",storyEn:"Born Boutrossieh in Himlaya in 1832, Rafqa entered religious life and became a Maronite nun. She joined the monastery of Saint Joseph in Jrabta, where she lived a life of prayer, humility and service. Her enduring faith through years of illness became central to her witness. Pope John Paul II canonized her in 2001.",storyAr:"وُلدت بطرسّية في حماليا سنة 1832، ودخلت الحياة الرهبانية وأصبحت راهبة مارونية. عاشت في دير مار يوسف في جربتا حياة صلاة وتواضع وخدمة. وتميّزت بثباتها في الإيمان خلال سنوات المرض. أعلنها البابا يوحنا بولس الثاني قديسة سنة 2001."},
    {en:"Estephan Nehme",ar:"الطوباوي إسطفان نعمه",letter:"S",status:"Blessed · 2010",place:"Lehfed · لحفد",years:"1889–1938",storyEn:"Estephan Nehme was born in Lehfed in 1889 and joined the Lebanese Maronite Order as a monk. He was known for a quiet life of prayer, humility and faithful work. He died in 1938 and was beatified by Pope Benedict XVI in 2010.",storyAr:"وُلد إسطفان نعمه في لحفد سنة 1889 وانضمّ إلى الرهبنة اللبنانية المارونية. عُرف بحياة هادئة من الصلاة والتواضع والعمل الأمين. توفّي سنة 1938 وأعلنه البابا بندكتس السادس عشر طوباويًا سنة 2010."},
    {en:"Leonard Melki",ar:"الطوباوي يوسف حبيب ملكي",letter:"L",status:"Blessed · Martyr",place:"Baskinta · بسكنتا",years:"1881–1915",storyEn:"Youssef Habib Melki, known as Leonard, was a Capuchin priest born in Baskinta. He served communities in the Ottoman Empire and was killed during the persecution of Christians in 1915. He was beatified in 2022 together with Thomas Saleh.",storyAr:"وُلد يوسف حبيب ملكي، المعروف بالأب ليونار، في بسكنتا وكان كاهنًا كبوشيًا. خدم جماعات مسيحية في الدولة العثمانية واستشهد خلال اضطهاد المسيحيين سنة 1915. أُعلن طوباويًا سنة 2022 مع الأب توما صالح."},
    {en:"Thomas Saleh",ar:"الطوباوي توما صالح",letter:"T",status:"Blessed · Martyr",place:"Baabdat · بعبدات",years:"1879–1917",storyEn:"Thomas Saleh was a Lebanese Capuchin priest from Baabdat. His ministry brought him to the region of present-day Turkey, where he endured imprisonment and persecution and died in 1917. He was beatified in 2022 with Leonard Melki.",storyAr:"كان توما صالح كاهنًا كبوشيًا لبنانيًا من بعبدات. قادته خدمته إلى منطقة تركيا الحالية، حيث تعرّض للسجن والاضطهاد وتوفّي سنة 1917. أُعلن طوباويًا سنة 2022 مع ليونار ملكي."},
    {en:"The Massabki Brothers",ar:"الإخوة الشهداء المسابكي",letter:"M",status:"Canonized saints · 2024",place:"Damascus; Maronite family from Lebanon · دمشق",years:"Martyred 1860",storyEn:"Francis, Abdel Moati and Raphael Massabki were three Maronite brothers from a Lebanese family living in Damascus. During the persecution of Christians in 1860, they refused to abandon their faith and were killed. Pope Francis canonized the Massabki brothers in October 2024.",storyAr:"كان فرنسيس وعبد المعطي ورفائيل المسابكي ثلاثة إخوة موارنة من عائلة لبنانية عاشت في دمشق. خلال اضطهاد المسيحيين سنة 1860، رفضوا التخلّي عن إيمانهم واستشهدوا. أعلن البابا فرنسيس الإخوة المسابكيين قديسين في تشرين الأول 2024."},
    {en:"Maron",ar:"القديس مارون",letter:"M",status:"Saint · Father of the Maronite tradition",place:"Syrian region; spiritual heritage of Lebanon",years:"Died c. 410",storyEn:"Maron was an ascetic priest and hermit whose prayer and way of life attracted disciples. The community that grew around his spiritual tradition became known as the Maronites. Although he lived before modern national borders, his legacy is deeply rooted in the history of the Maronite Church in Lebanon.",storyAr:"كان مارون كاهنًا وناسكًا عاش حياة نسك وصلاة، واجتمع حوله تلاميذ تأثّروا بروحانيته. ونمت من هذا التقليد الجماعة التي عُرفت لاحقًا بالموارنة. ورغم أنه عاش قبل نشوء الحدود الوطنية الحديثة، فإن إرثه متجذّر في تاريخ الكنيسة المارونية في لبنان."}
  ];
  entries.push(...[{"en":"John Mark","ar":"القديس يوحنا مرقس","letter":"J","status":"Saint · Bishop","place":"Lebanon · early Church","years":"1st century","storyEn":"Early Christian tradition associates John Mark with the apostolic Church and the Gospel bearing his name. The Lebanese catalogue lists him among saints connected with the country; details of his life are drawn from early Christian tradition.","storyAr":"يربط التقليد المسيحيّ القديم يوحنا مرقس بالكنيسة الرسوليّة وبالإنجيل الذي يحمل اسمه. وتُدرجه لوائح القديسين المرتبطين بلبنان، فيما تستند تفاصيل حياته إلى التقليد المسيحيّ الأوّل."},{"en":"Nilus of Egypt","ar":"القديس نيلس","letter":"N","status":"Saint · Bishop","place":"Lebanon · ancient martyrdom tradition","years":"Died c. 303","storyEn":"Nilus is remembered in early Christian martyrology among bishops associated with persecutions in the eastern Roman provinces. The surviving details are limited, so his entry is kept brief and identified as an early tradition.","storyAr":"يُذكر نيلس في سنكسارات الشهداء المسيحيّين الأوائل ضمن الأساقفة المرتبطين باضطهادات المقاطعات الشرقيّة للإمبراطوريّة الرومانيّة. والمعلومات التاريخيّة المتبقيّة عنه محدودة."},{"en":"Peleus","ar":"القديس بيليوس","letter":"P","status":"Saint · Bishop","place":"Lebanon · ancient martyrdom tradition","years":"Died c. 303","storyEn":"Peleus is listed in early Christian martyrologies among bishops who suffered during the persecutions under Diocletian. His commemoration is preserved in the Church's ancient memory.","storyAr":"يَرِد اسم بيليوس في السنكسارات المسيحيّة القديمة بين الأساقفة الذين استشهدوا في اضطهادات دقلديانوس. وقد حُفظ تذكاره في الذاكرة الكنسيّة القديمة."},{"en":"Silvanus","ar":"القديس سيلفانوس","letter":"S","status":"Saint · Bishop","place":"Lebanon · ancient tradition","years":"Died c. 303","storyEn":"Silvanus is honoured in the ancient Christian tradition as a bishop and martyr. Historical details are sparse, and later calendars preserve his name among witnesses of the early Church.","storyAr":"يُكرَّم سيلفانوس في التقليد المسيحيّ القديم كأسقف وشهيد. وتبقى تفاصيل حياته قليلة، فيما تحفظه التقاويم الكنسيّة بين شهود الكنيسة الأولى."},{"en":"Tyrannio of Tyre","ar":"القديس تيرانيون","letter":"T","status":"Saint · Bishop and martyr","place":"Tyre · صور","years":"Died c. 311","storyEn":"Tyrannio is associated in Christian martyrologies with the early Church of Tyre and the persecutions of the third and fourth centuries. He is remembered as a bishop who bore witness to his faith.","storyAr":"يرتبط اسم تيرانيون في السنكسارات المسيحيّة بكنيسة صور في القرنين الثالث والرابع. ويُذكر كأسقف شهد لإيمانه في زمن الاضطهاد."},{"en":"Zenobius of Sidon","ar":"القديس زينوبius","letter":"Z","status":"Saint · Priest and martyr","place":"Sidon · صيدا","years":"Early 4th century","storyEn":"Zenobius is remembered in eastern Christian tradition as a priest and martyr connected with the Phoenician coast. The historical record is brief, and traditions differ on some details.","storyAr":"يُذكر زينوبius في التقليد المسيحيّ الشرقيّ كاهنًا وشهيدًا مرتبطًا بالساحل الفينيقيّ. والمعلومات التاريخيّة عنه موجزة وتختلف بعض الروايات في تفاصيلها."},{"en":"Vulpian of Tyre","ar":"القديس فولبيانوس","letter":"V","status":"Saint · Martyr","place":"Tyre · صور","years":"Died c. 304","storyEn":"Vulpian is named in ancient martyrologies as a Christian martyr of Tyre during the persecution under Diocletian. His memory belongs to the early Christian history of the Lebanese coast.","storyAr":"يَرِد فولبيانوس في السنكسارات القديمة كشهيد مسيحيّ من صور في زمن اضطهاد دقلديانوس. ويرتبط تذكاره بتاريخ المسيحيّة الأولى على الساحل اللبنانيّ."},{"en":"Cyril of Heliopolis","ar":"القديس كيرلس","letter":"C","status":"Saint · Deacon and martyr","place":"Lebanon · ancient tradition","years":"Died c. 362","storyEn":"Cyril is recorded in eastern Christian calendars among the martyrs of the fourth century. The details of his ministry and death are preserved only in brief martyrological notices.","storyAr":"يُسجَّل كيرلس في التقاويم المسيحيّة الشرقيّة بين شهداء القرن الرابع. ولم تصلنا عن خدمته واستشهاده سوى إشارات موجزة في السنكسارات."},{"en":"Dorotheus","ar":"القديس دوروثاوس","letter":"D","status":"Saint · Bishop","place":"Lebanon · ancient tradition","years":"Died c. 363","storyEn":"Dorotheus appears in ancient Christian lists of bishops and martyrs connected with the eastern Mediterranean. Because accounts are fragmentary, his biography is presented cautiously.","storyAr":"يظهر دوروثاوس في لوائح مسيحيّة قديمة لأساقفة وشهداء ارتبطوا بشرق المتوسّط. ولأن الروايات مجتزأة، تُعرض سيرته بحذر."},{"en":"Nerses I the Great","ar":"القديس نرسيس الكبير","letter":"N","status":"Saint · Armenian bishop","place":"Armenia · Armenian Christian heritage","years":"4th century","storyEn":"Nerses I was a major Armenian Church leader who promoted Christian teaching, charitable institutions and care for the poor. His story is included as part of the wider Christian heritage of the region, not as a Lebanese-born saint.","storyAr":"كان نرسيس الأوّل من أبرز قادة الكنيسة الأرمنيّة، وعمل على نشر التعليم المسيحيّ وإنشاء مؤسّسات خيريّة والعناية بالفقراء. ندرجه ضمن التراث المسيحيّ الأوسع في المنطقة، لا كقديس مولود في لبنان."},{"en":"Frumentius","ar":"القديس فرومنتيوس","letter":"F","status":"Saint · Bishop","place":"Lebanon connection in ancient tradition","years":"4th century","storyEn":"Frumentius is remembered as the missionary bishop who helped establish Christianity in the Kingdom of Aksum, in present-day Ethiopia and Eritrea. Some lists associate his early life with the Levant; the strongest part of his legacy is his Ethiopian mission.","storyAr":"يُذكر فرومنتيوس كأسقف مرسل ساهم في ترسيخ المسيحيّة في مملكة أكسوم، في إثيوبيا وإريتريا حاليًا. تربط بعض اللوائح بدايات حياته بالمشرق، أمّا أبرز إرثه فهو رسالته في إثيوبيا."},{"en":"Leontius","ar":"القديس ليونتيوس","letter":"L","status":"Saint · Martyr","place":"Lebanon · early Christian tradition","years":"4th century","storyEn":"Leontius is a name preserved in early Christian martyrologies associated with the eastern Mediterranean. As the surviving biographical record is uncertain, this entry distinguishes traditional veneration from documented biography.","storyAr":"ليونتيوس اسم محفوظ في السنكسارات المسيحيّة الأولى المرتبطة بشرق المتوسّط. وبما أنّ المعلومات السيريّة غير مؤكّدة، تميّز هذه البطاقة بين الإكرام التقليديّ والسيرة الموثّقة."},{"en":"Nonnus of Edessa","ar":"القديس نونّوس","letter":"N","status":"Saint · Bishop","place":"Eastern Christian tradition","years":"5th century","storyEn":"Nonnus is remembered in eastern Christian tradition as a bishop associated with the spiritual history of Edessa. Accounts of his life are preserved mainly through later ecclesiastical tradition.","storyAr":"يُذكر نونّوس في التقليد المسيحيّ الشرقيّ كأسقف ارتبط بالتاريخ الروحيّ لمدينة الرها. وقد حُفظت أخبار حياته أساسًا في التقاليد الكنسيّة اللاحقة."},{"en":"Elias Hoayek","ar":"البطريرك الطوباوي إلياس الحويّك","letter":"E","status":"Blessed · Maronite patriarch","place":"Helta · الحيطة","years":"1843–1931","storyEn":"Elias Hoayek served as Maronite patriarch from 1899 to 1931 and played a major role in the modern history of Lebanon, including the period surrounding the proclamation of Greater Lebanon in 1920. His cause for sainthood is distinct from canonisation; he is not presented here as a canonised saint.","storyAr":"خدم إلياس الحويّك بطريركًا مارونيًا بين 1899 و1931، وكان له دور بارز في تاريخ لبنان الحديث، ولا سيّما في المرحلة التي رافقت إعلان دولة لبنان الكبير سنة 1920. وتبقى قضيّة تطويبه منفصلة عن إعلان القداسة، لذلك لا نقدّمه هنا كقديس مُعلن."},{"en":"Yaqub Haddad","ar":"الطوباوي يعقوب الكبّوشي","letter":"Y","status":"Blessed · Capuchin priest","place":"Ghazeer · غزير","years":"1875–1954","storyEn":"Khalil Haddad, known as Father Yaqub, was a Lebanese Capuchin priest who founded the Franciscan Sisters of the Cross. He devoted his ministry to the poor, the sick and people in need, and was beatified in 2008.","storyAr":"كان خليل حدّاد، المعروف بالأب يعقوب، كاهنًا كبّوشيًا لبنانيًا أسّس راهبات الصليب الفرنسيسكانيّات. كرّس خدمته للفقراء والمرضى والمحتاجين، وأُعلن طوباويًا سنة 2008."},{"en":"Béchara Abou Mrad","ar":"الأب بشارة أبو مراد","letter":"B","status":"Servant of God · Melkite priest","place":"Zahlé · زحلة","years":"1853–1930","storyEn":"Béchara Abou Mrad was a Melkite priest from Lebanon remembered for his pastoral service and spiritual life. His cause has been introduced, but he should be described as a Servant of God rather than a blessed or canonised saint.","storyAr":"كان بشارة أبو مراد كاهنًا ملكيًا من لبنان، عُرف بخدمته الرعويّة وحياته الروحيّة. وقد فُتحت قضيّة تطويبه، لكنّ اللقب الدقيق له هو خادم الله، لا طوباوي أو قديس مُعلن."},{"en":"Francis of Assisi","ar":"القديس فرنسيس الأسيزي","letter":"F","status":"Saint · Founder","place":"Assisi, Italy","years":"1181/82–1226","storyEn":"Francis gave up wealth to live simply, serve people who were poor and care for creation. He founded the Franciscan movement and became one of Christianity's best-known witnesses to humility and peace.","storyAr":"تخلّى فرنسيس عن الغنى ليعيش ببساطة ويخدم الفقراء ويعتني بالخليقة. أسّس الحركة الفرنسيسكانيّة وأصبح من أشهر شهود التواضع والسلام في المسيحيّة."},{"en":"Clare of Assisi","ar":"القديسة كلارا الأسيزيّة","letter":"C","status":"Saint · Founder","place":"Assisi, Italy","years":"1194–1253","storyEn":"Clare followed the example of Francis and founded the Poor Clares. She chose a life of prayer, simplicity and community, becoming a model of courage and devotion.","storyAr":"اقتدت كلارا بفرنسيس وأسّست جماعة الكلاريسات الفقيرات. اختارت حياة الصلاة والبساطة والأخوّة، وأصبحت مثالًا للشجاعة والتعبّد."},{"en":"Augustine of Hippo","ar":"القديس أوغسطينوس","letter":"A","status":"Saint · Bishop and Doctor","place":"Hippo, North Africa","years":"354–430","storyEn":"After a restless search for truth, Augustine became a Christian and later bishop of Hippo. His writings, especially Confessions, shaped Christian thought for centuries.","storyAr":"بعد بحث طويل عن الحقيقة، اعتنق أوغسطينوس المسيحيّة وأصبح أسقف هيبّون. أثّرت كتاباته، ولا سيّما الاعترافات، في الفكر المسيحيّ قرونًا طويلة."},{"en":"Monica","ar":"القديسة مونيكا","letter":"M","status":"Saint · Mother","place":"North Africa","years":"c. 331–387","storyEn":"Monica is remembered for her patient faith and persistent prayer for her family, especially her son Augustine. Her story is often shared as an example of hope and steadfast love.","storyAr":"تُذكر مونيكا لإيمانها الصبور وصلاتها الدائمة من أجل عائلتها، ولا سيّما ابنها أوغسطينوس. وتُروى قصّتها مثالًا للرجاء والمحبّة الثابتة."},{"en":"Benedict of Nursia","ar":"القديس بندكتس","letter":"B","status":"Saint · Founder","place":"Nursia, Italy","years":"c. 480–547","storyEn":"Benedict shaped western monastic life through a rule that balances prayer, work, hospitality and community. His Rule became a foundation for many monasteries.","storyAr":"ساهم بندكتس في تشكيل الحياة الرهبانيّة الغربيّة من خلال قاعدة توازن بين الصلاة والعمل والضيافة والحياة المشتركة. وأصبحت قاعدته أساسًا لأديرة كثيرة."},{"en":"Anthony the Great","ar":"القديس أنطونيوس الكبير","letter":"A","status":"Saint · Desert Father","place":"Egypt","years":"c. 251–356","storyEn":"Anthony gave away his inheritance and embraced a life of prayer in the Egyptian desert. He became a central figure in Christian monasticism and inspired generations of monks.","storyAr":"وزّع أنطونيوس ميراثه واختار حياة الصلاة في صحراء مصر. وأصبح من أبرز آباء الرهبنة المسيحيّة وألهم أجيالًا من الرهبان."},{"en":"Athanasius of Alexandria","ar":"القديس أثناسيوس","letter":"A","status":"Saint · Bishop and Doctor","place":"Alexandria, Egypt","years":"c. 296–373","storyEn":"Athanasius defended the Christian teaching about Christ during the Arian controversy and served as bishop of Alexandria. His writings helped shape the Church's understanding of the Incarnation.","storyAr":"دافع أثناسيوس عن التعليم المسيحيّ حول شخص المسيح خلال الجدل الآريوسيّ، وخدم أسقفًا للإسكندريّة. وأسهمت كتاباته في صياغة فهم الكنيسة للتجسّد."},{"en":"Basil the Great","ar":"القديس باسيليوس الكبير","letter":"B","status":"Saint · Bishop and Doctor","place":"Cappadocia","years":"c. 330–379","storyEn":"Basil was a bishop, theologian and organiser of charitable care. He encouraged communities to serve people in need and helped shape eastern Christian monastic life.","storyAr":"كان باسيليوس أسقفًا ولاهوتيًا ومنظّمًا لأعمال المحبّة. شجّع الجماعات على خدمة المحتاجين وأسهم في بناء الحياة الرهبانيّة المسيحيّة الشرقيّة."},{"en":"Gregory Nazianzen","ar":"القديس غريغوريوس النزينزي","letter":"G","status":"Saint · Bishop and Doctor","place":"Cappadocia","years":"c. 329–390","storyEn":"Gregory became known for his theological orations and his teaching about the Trinity. His work earned him a lasting place among the great teachers of the early Church.","storyAr":"اشتهر غريغوريوس بعظاته اللاهوتيّة وتعليمه حول الثالوث الأقدس. ومنحته كتاباته مكانة راسخة بين كبار معلّمي الكنيسة الأولى."},{"en":"John Chrysostom","ar":"القديس يوحنا الذهبيّ الفم","letter":"J","status":"Saint · Bishop and Doctor","place":"Antioch & Constantinople","years":"c. 347–407","storyEn":"John was a gifted preacher whose clear sermons called people to live the Gospel and care for the poor. His liturgical tradition remains especially important in eastern Christianity.","storyAr":"كان يوحنا واعظًا موهوبًا دعت عظاته الواضحة الناس إلى عيش الإنجيل والاهتمام بالفقراء. ولا يزال التقليد الليتورجيّ المرتبط به مهمًا في المسيحيّة الشرقيّة."},{"en":"Nicholas of Myra","ar":"القديس نيقولاوس","letter":"N","status":"Saint · Bishop","place":"Myra, Lycia","years":"4th century","storyEn":"Nicholas is remembered as a bishop known for generosity and care for people in need. Stories about his discreet acts of charity helped make him one of the most beloved saints across Christian traditions.","storyAr":"يُذكر نيقولاوس كأسقف عُرف بالسخاء والاهتمام بالمحتاجين. وأسهمت قصص عطائه الخفيّ في جعله من أكثر القديسين محبّة في التقاليد المسيحيّة."},{"en":"George","ar":"القديس جاورجيوس","letter":"G","status":"Saint · Martyr","place":"Early Christian tradition","years":"Traditionally 3rd–4th century","storyEn":"George is venerated as a Christian martyr whose courage became a symbol of steadfast faith. Many cultures tell stories about him, but the details of the dragon legend belong to later tradition.","storyAr":"يُكرَّم جاورجيوس كشَهيد مسيحيّ أصبحت شجاعته رمزًا للثبات في الإيمان. وتروي ثقافات كثيرة قصصًا عنه، أمّا حكاية التنّين فتعود إلى تقاليد لاحقة."},{"en":"Lucy of Syracuse","ar":"القديسة لوسيا","letter":"L","status":"Saint · Martyr","place":"Syracuse, Sicily","years":"Died c. 304","storyEn":"Lucy is remembered as an early Christian martyr from Syracuse. Her name became associated with light, and devotion to her spread widely through the Christian world.","storyAr":"تُذكر لوسيا كشهيدة مسيحيّة من سيراكوزا. ارتبط اسمها بالنور، وانتشر إكرامها على نطاق واسع في العالم المسيحيّ."},{"en":"Agnes of Rome","ar":"القديسة أغنيس","letter":"A","status":"Saint · Martyr","place":"Rome","years":"Died c. 304","storyEn":"Agnes is honoured as a young Roman martyr who remained faithful to her Christian convictions. Her witness became a lasting symbol of courage and fidelity.","storyAr":"تُكرَّم أغنيس كشابّة رومانيّة شهيدة تمسّكت بمعتقداتها المسيحيّة. وأصبحت شهادتها رمزًا دائمًا للشجاعة والأمانة."},{"en":"Cecilia","ar":"القديسة سيسيليا","letter":"C","status":"Saint · Martyr","place":"Rome","years":"Early Christian tradition","storyEn":"Cecilia is venerated as a Roman martyr and is traditionally regarded as the patron saint of music. Her story has inspired centuries of sacred art and music.","storyAr":"تُكرَّم سيسيليا كشهيدة رومانيّة، ويعتبرها التقليد شفيعة الموسيقى. وقد ألهمت قصّتها الفنّ والموسيقى المقدّسة عبر القرون."},{"en":"Patrick of Ireland","ar":"القديس باتريك","letter":"P","status":"Saint · Missionary","place":"Ireland","years":"5th century","storyEn":"Patrick was a missionary bishop who helped spread Christianity in Ireland. His writings and later traditions remember a life devoted to preaching, prayer and forming Christian communities.","storyAr":"كان باتريك أسقفًا مرسلًا ساهم في انتشار المسيحيّة في إيرلندا. وتذكر كتاباته والتقاليد اللاحقة حياة كرّسها للكرازة والصلاة وتأسيس الجماعات المسيحيّة."},{"en":"Francis Xavier","ar":"القديس فرنسيس كسفاريوس","letter":"F","status":"Saint · Missionary","place":"Navarre, Spain; Asia","years":"1506–1552","storyEn":"Francis Xavier was a Jesuit missionary who travelled through India, Southeast Asia and Japan. His letters describe his work sharing the Christian faith across cultures.","storyAr":"كان فرنسيس كسفاريوس مرسلًا يسوعيًا جاب الهند وجنوب شرق آسيا واليابان. وتصف رسائله عمله في مشاركة الإيمان المسيحيّ عبر ثقافات مختلفة."},{"en":"Ignatius of Loyola","ar":"القديس إغناطيوس دي لويولا","letter":"I","status":"Saint · Founder","place":"Basque Country, Spain","years":"c. 1491–1556","storyEn":"After a serious injury changed his life, Ignatius turned toward prayer and spiritual discernment. He founded the Society of Jesus, known as the Jesuits, and developed the Spiritual Exercises.","storyAr":"بعد إصابة خطيرة غيّرت حياته، اتّجه إغناطيوس إلى الصلاة والتمييز الروحيّ. أسّس جمعيّة يسوع، المعروفة باليسوعيّين، ووضع الرياضات الروحيّة."},{"en":"Teresa of Ávila","ar":"القديسة تريزا الأفيليّة","letter":"T","status":"Saint · Doctor of the Church","place":"Ávila, Spain","years":"1515–1582","storyEn":"Teresa was a Carmelite reformer and spiritual writer who taught about prayer and friendship with God. Her works remain important guides to the contemplative life.","storyAr":"كانت تريزا مصلحة كرملية وكاتبة روحيّة علّمت عن الصلاة والصداقة مع الله. ولا تزال مؤلّفاتها أدلّة مهمّة للحياة التأمّليّة."},{"en":"John of the Cross","ar":"القديس يوحنا الصليب","letter":"J","status":"Saint · Doctor of the Church","place":"Spain","years":"1542–1591","storyEn":"John was a Carmelite priest, poet and spiritual teacher. His writings describe the journey of faith, purification and union with God.","storyAr":"كان يوحنا كاهنًا كرملّيًا وشاعرًا ومعلّمًا روحيًا. تصف كتاباته مسيرة الإيمان والتطهير والاتّحاد بالله."},{"en":"Thérèse of Lisieux","ar":"القديسة تريزيا الطفل يسوع","letter":"T","status":"Saint · Doctor of the Church","place":"Lisieux, France","years":"1873–1897","storyEn":"Thérèse entered the Carmelite convent as a young woman and taught what she called the Little Way: trusting God through small acts of love. Her autobiography became widely read.","storyAr":"دخلت تريزيا دير الكرمل وهي شابّة، وعلّمت ما سمّته الطريق الصغيرة: الثقة بالله من خلال أعمال المحبّة البسيطة. وانتشرت سيرتها الذاتيّة على نطاق واسع."},{"en":"John Bosco","ar":"القديس يوحنا بوسكو","letter":"J","status":"Saint · Educator","place":"Turin, Italy","years":"1815–1888","storyEn":"Don Bosco devoted his life to educating and accompanying young people, especially those who were poor or vulnerable. He founded the Salesians and promoted education rooted in kindness and faith.","storyAr":"كرّس دون بوسكو حياته لتربية الشباب ومرافقتهم، ولا سيّما الفقراء والمعرّضين للخطر. أسّس الرهبنة السالسيّة وشجّع تربية تقوم على اللطف والإيمان."},{"en":"Vincent de Paul","ar":"القديس منصور دي بول","letter":"V","status":"Saint · Priest","place":"France","years":"1581–1660","storyEn":"Vincent organised practical service for people living in poverty and helped renew charitable ministry in the Church. His legacy inspired the Vincentian family and many works of service.","storyAr":"نظّم منصور خدمة عمليّة للفقراء وأسهم في تجديد العمل الخيريّ في الكنيسة. وألهم إرثه العائلة الفنسنتيّة وأعمال خدمة كثيرة."},{"en":"Martin de Porres","ar":"القديس مارتن دي بورّيس","letter":"M","status":"Saint · Dominican brother","place":"Lima, Peru","years":"1579–1639","storyEn":"Martin was a Dominican brother known for humility, care for the sick and service to people across social divisions. He is remembered as a witness to compassion and equality.","storyAr":"كان مارتن أخًا دومينيكانيًا عُرف بالتواضع والعناية بالمرضى وخدمة الناس من مختلف الطبقات. ويُذكر شاهدًا على الرحمة والمساواة."},{"en":"Rose of Lima","ar":"القديسة روزا دي ليما","letter":"R","status":"Saint · Lay Dominican","place":"Lima, Peru","years":"1586–1617","storyEn":"Rose lived a life of prayer and service, caring especially for people who were poor and ill. She became the first person from the Americas to be canonised.","storyAr":"عاشت روزا حياة صلاة وخدمة، واهتمّت خصوصًا بالفقراء والمرضى. وأصبحت أوّل شخص من الأميركتين يُعلن قديسًا."},{"en":"Kateri Tekakwitha","ar":"القديسة كاتيري تيكاكويثا","letter":"K","status":"Saint · Laywoman","place":"Mohawk territory / Canada","years":"1656–1680","storyEn":"Kateri was a Mohawk woman who became Christian and lived a life of prayer and service despite difficulties. She is honoured as the first Indigenous person from North America to be canonised.","storyAr":"كانت كاتيري امرأة من شعب الموهوك اعتنقت المسيحيّة وعاشت حياة صلاة وخدمة رغم الصعوبات. وتُكرَّم كأوّل شخص من سكّان أميركا الأصليّين في أميركا الشماليّة يُعلن قديسًا."},{"en":"Josephine Bakhita","ar":"القديسة جوزفين بخيتة","letter":"J","status":"Saint · Religious sister","place":"Sudan & Italy","years":"c. 1869–1947","storyEn":"Bakhita was born in Sudan and endured enslavement before finding freedom in Italy. She became a Canossian sister and is remembered for forgiveness, dignity and hope.","storyAr":"وُلدت بخيتة في السودان وعانت الاستعباد قبل أن تنال الحرّيّة في إيطاليا. أصبحت راهبة كانوسيّة وتُذكر للمغفرة والكرامة والرجاء."},{"en":"Maximilian Kolbe","ar":"القديس مكسيميليان كولبه","letter":"M","status":"Saint · Franciscan priest","place":"Poland","years":"1894–1941","storyEn":"Maximilian Kolbe was a Franciscan priest who founded a media apostolate and was imprisoned during the Second World War. He is remembered for an act of self-giving love at Auschwitz.","storyAr":"كان مكسيميليان كولبه كاهنًا فرنسيسكانيًا أسّس عملًا تبشيريًا إعلاميًا وسُجن خلال الحرب العالميّة الثانية. ويُذكر لموقفه الذي جسّد المحبّة وبذل الذات في أوشفيتز."},{"en":"Oscar Romero","ar":"القديس أوسكار روميرو","letter":"O","status":"Saint · Archbishop and martyr","place":"El Salvador","years":"1917–1980","storyEn":"Oscar Romero spoke publicly for the dignity of the poor and called for an end to violence in El Salvador. He was killed while celebrating Mass and canonised in 2018.","storyAr":"دافع أوسكار روميرو علنًا عن كرامة الفقراء ودعا إلى إنهاء العنف في السلفادور. قُتل أثناء احتفاله بالقدّاس وأُعلن قديسًا سنة 2018."},{"en":"Mother Teresa of Calcutta","ar":"القديسة الأم تريزا","letter":"M","status":"Saint · Founder","place":"Skopje; ministry in India","years":"1910–1997","storyEn":"Mother Teresa founded the Missionaries of Charity and served people who were poor and sick in Kolkata and beyond. Her work became known around the world; she was canonised in 2016.","storyAr":"أسّست الأم تريزا راهبات مرسلات المحبّة وخدمت الفقراء والمرضى في كولكاتا وخارجها. اشتهر عملها في العالم وأُعلنت قديسة سنة 2016."},{"en":"John Paul II","ar":"القديس البابا يوحنا بولس الثاني","letter":"J","status":"Saint · Pope","place":"Poland & Vatican","years":"1920–2005","storyEn":"John Paul II served as pope from 1978 to 2005 and travelled widely, encouraging dialogue, peace and the dignity of every person. He was canonised in 2014.","storyAr":"خدم يوحنا بولس الثاني بابا من 1978 إلى 2005، وسافر كثيرًا مشجّعًا الحوار والسلام وكرامة كل إنسان. أُعلن قديسًا سنة 2014."},{"en":"Paul VI","ar":"القديس البابا بولس السادس","letter":"P","status":"Saint · Pope","place":"Italy & Vatican","years":"1897–1978","storyEn":"Paul VI guided the Church through the closing years of the Second Vatican Council and its early implementation. He promoted dialogue with the modern world and was canonised in 2018.","storyAr":"قاد بولس السادس الكنيسة خلال السنوات الأخيرة من المجمع الفاتيكاني الثاني وبداية تطبيق قراراته. وشجّع الحوار مع العالم الحديث وأُعلن قديسًا سنة 2018."},{"en":"John XXIII","ar":"القديس البابا يوحنا الثالث والعشرون","letter":"J","status":"Saint · Pope","place":"Italy & Vatican","years":"1881–1963","storyEn":"John XXIII convoked the Second Vatican Council, seeking renewal and a more open dialogue between the Church and the world. He was canonised in 2014.","storyAr":"دعا يوحنا الثالث والعشرون إلى المجمع الفاتيكاني الثاني سعيًا إلى تجديد الكنيسة وحوار أوسع بينها وبين العالم. أُعلن قديسًا سنة 2014."},{"en":"Pier Giorgio Frassati","ar":"القديس بيير جورجيو فراسّاتي","letter":"P","status":"Saint · Layman","place":"Turin, Italy","years":"1901–1925","storyEn":"Pier Giorgio was a young Italian layman who loved the mountains, friendship and serving people in poverty. His faith shaped an active life of charity and public responsibility.","storyAr":"كان بيير جورجيو شابًا إيطاليًا أحبّ الجبال والصداقة وخدمة الفقراء. شكّل إيمانه حياة عمليّة من المحبّة والمسؤوليّة الاجتماعيّة."},{"en":"Carlo Acutis","ar":"القديس كارلو أكوتيس","letter":"C","status":"Saint · Layman","place":"London & Italy","years":"1991–2006","storyEn":"Carlo was a young Catholic who used his computer skills to document Eucharistic miracles and share his faith online. He is remembered for combining ordinary teenage life with prayer and service.","storyAr":"كان كارلو شابًا كاثوليكيًا استخدم مهاراته الرقميّة لتوثيق المعجزات الإفخارستيّة ومشاركة إيمانه عبر الإنترنت. ويُذكر لجمعه بين الحياة اليوميّة والصلاة والخدمة."},{"en":"Elizabeth of Hungary","ar":"القديسة إليصابات المجريّة","letter":"E","status":"Saint · Princess and charitable worker","place":"Hungary & Germany","years":"1207–1231","storyEn":"Elizabeth used her position and resources to care for people who were poor and sick. After her husband's death she devoted herself more fully to charitable service.","storyAr":"استخدمت إليصابات مكانتها ومواردها للعناية بالفقراء والمرضى. وبعد وفاة زوجها كرّست نفسها بصورة أكبر لأعمال المحبّة والخدمة."},{"en":"Catherine of Siena","ar":"القديسة كاترينا السيانيّة","letter":"C","status":"Saint · Doctor of the Church","place":"Siena, Italy","years":"1347–1380","storyEn":"Catherine was a Dominican laywoman, mystic and writer who urged Church leaders toward reform and reconciliation. Her letters and spiritual writings remain influential.","storyAr":"كانت كاترينا علمانيّة دومينيكانيّة ومتأمّلة وكاتبة دعت قادة الكنيسة إلى الإصلاح والمصالحة. ولا تزال رسائلها وكتاباتها الروحيّة مؤثّرة."}]);
  entries.forEach((entry, index) => { entry.group = index < 12 ? "Lebanese" : (index < 28 ? "Lebanese" : "Worldwide"); });
  entries.push(...[{"en":"John Maron","ar":"القديس يوحنا مارون","letter":"J","status":"Saint · First Maronite patriarch","place":"Kfarhay · كفرحي، شمال لبنان","years":"Died traditionally c. 707","storyEn":"John Maron is venerated as the first Maronite patriarch and one of the central figures in the formation of the Maronite Church. Church tradition connects his ministry with the communities of Mount Lebanon and the northern coastal region. He is remembered not simply as a church leader, but as a shepherd who helped a community preserve its worship, identity and communion through a period of political and theological conflict. Accounts of his life were written many generations later, and dates and details differ between sources; this biography therefore distinguishes the strong place of his memory in Maronite tradition from details that cannot be firmly reconstructed.","storyAr":"يُكرَّم يوحنا مارون بوصفه أوّل بطريرك ماروني، ومن الشخصيّات الأساسيّة في نشأة الكنيسة المارونيّة. ويربط التقليد الكنسي خدمته بجماعات جبل لبنان والمنطقة الساحليّة الشماليّة. ولا يُذكر فقط كقائد كنسي، بل كراعٍ ساعد جماعته على صون عبادتها وهويّتها وشركتها الكنسيّة وسط صراعات سياسيّة ولاهوتيّة. كُتبت أخبار حياته بعد أجيال من زمنه، وتختلف المصادر في بعض التواريخ والتفاصيل؛ لذلك تميّز هذه السيرة بين مكانته الراسخة في الذاكرة المارونيّة وبين التفاصيل التي يصعب إثباتها تاريخيًّا."},{"en":"Theodosia of Tyre","ar":"القديسة ثيودوسيا من صور","letter":"T","status":"Saint · Martyr in ancient tradition","place":"Tyre · صور","years":"Early 4th century · traditionally c. 307","storyEn":"Theodosia is remembered in Christian martyrology as a young Christian woman of Tyre during the Great Persecution. The traditional account says that she approached imprisoned Christians to encourage them and was herself arrested. Her story became a witness to the courage of ordinary believers who supported one another when public profession of Christianity could bring danger. The surviving accounts belong to the ancient hagiographical tradition and should be read with the care normally given to early martyr narratives; the historical record does not provide a modern biography or independently verifiable details for every episode.","storyAr":"تُذكر ثيودوسيا في السنكسارات المسيحيّة كشابّة مسيحيّة من صور عاشت في زمن الاضطهاد الكبير. وتروي السيرة التقليديّة أنّها اقتربت من مسيحيّين مسجونين لتشجّعهم، فاعتُقلت هي أيضًا. وأصبحت قصّتها شهادة على شجاعة المؤمنين العاديّين الذين ساند بعضهم بعضًا حين كان إعلان الإيمان بالمسيحيّة يعرّضهم للخطر. تنتمي الأخبار المتبقيّة إلى تقليد سير الشهداء القديم، وينبغي قراءتها مع التنبّه إلى أنّ المصادر لا تقدّم سيرة حديثة موثّقة لكلّ تفاصيل الرواية."},{"en":"Eudocia of Heliopolis","ar":"القديسة أفدوكيا من هليوبوليس","letter":"E","status":"Saint · Martyr in ancient tradition","place":"Heliopolis · بعلبك","years":"Ancient tradition · 2nd century","storyEn":"Eudocia is associated in Eastern Christian tradition with Heliopolis, the ancient city at the site of modern Baalbek. Her traditional story describes a woman who turned away from her former life after hearing Christian teaching and reading the Scriptures, then devoted herself to prayer and charity. Later accounts describe her as suffering martyrdom. The details and chronology vary across hagiographical sources, so the website presents her as a figure of local Christian memory rather than claiming that every episode is historically established.","storyAr":"يرتبط اسم أفدوكيا في التقليد المسيحي الشرقي بهليوبوليس، المدينة القديمة التي تقوم في موقع بعلبك اليوم. وتروي سيرتها التقليديّة أنّها ابتعدت عن حياتها السابقة بعدما سمعت التعليم المسيحي وقرأت الكتب المقدّسة، ثم كرّست نفسها للصلاة وأعمال الرحمة. وتذكر روايات لاحقة أنّها نالت إكليل الشهادة. تختلف التفاصيل والتواريخ بين مصادر سير القديسين، لذلك تعرضها هذه الصفحة كشخصيّة من الذاكرة المسيحيّة المحليّة، من دون اعتبار كلّ أحداث الرواية مثبتة تاريخيًّا."},{"en":"Pamphilus of Beirut","ar":"القديس بامفيلس من بيروت","letter":"P","status":"Saint · Priest and martyr","place":"Beirut · بيروت; ministry in Caesarea","years":"Died 309","storyEn":"Pamphilus was a Christian priest and scholar remembered for his work in Caesarea Maritima, where he helped build an important Christian library and supported the careful copying and study of Scripture. Ancient sources associate his origins with Beirut. During the persecution under Emperor Diocletian, he was imprisoned and later executed. His legacy is especially important for the history of biblical scholarship: he represents the early Church’s effort to preserve, study and transmit Christian texts as well as its witness under persecution. Some biographical details come from ancient ecclesiastical histories.","storyAr":"كان بامفيلس كاهنًا وعالمًا مسيحيًّا يُذكر بعمله في قيصريّة البحريّة، حيث ساهم في إنشاء مكتبة مسيحيّة مهمّة وفي نسخ الكتاب المقدّس ودراسته بعناية. وتربط مصادر قديمة أصوله بمدينة بيروت. خلال اضطهاد الإمبراطور دقلديانوس، سُجن ثم أُعدم. وتكمن أهميّة إرثه خصوصًا في تاريخ الدراسات الكتابيّة؛ فهو يمثّل سعي الكنيسة الأولى إلى حفظ النصوص المسيحيّة ودراستها ونقلها، إلى جانب شهادتها للإيمان في زمن الاضطهاد. وتستند بعض تفاصيل سيرته إلى تواريخ كنسيّة قديمة."},{"en":"Christina of Tyre","ar":"القديسة كريستينا من صور","letter":"C","status":"Saint · Martyr in ancient tradition","place":"Tyre · صور","years":"Ancient tradition · 4th century","storyEn":"Christina of Tyre appears in some local and later Christian accounts as a young woman who rejected the worship of idols and chose the Christian faith. The stories describe conflict with her family and authorities, followed by martyrdom. Her account is sometimes confused with other saints named Christina, especially Christina of Bolsena; the historical traditions are not always consistent. This profile keeps the Tyrian association visible while noting that the details belong to hagiographical tradition and require careful source distinction.","storyAr":"تظهر كريستينا من صور في بعض الروايات المسيحيّة المحليّة والمتأخّرة كشابّة رفضت عبادة الأصنام واختارت الإيمان المسيحي. وتروي القصص خلافًا بينها وبين عائلتها والسلطات، ثم استشهادها. وقد تختلط سيرتها أحيانًا بسِيَر قديسات أخريات يحملن اسم كريستينا، ولا سيّما كريستينا من بولسينا، كما أنّ الروايات التاريخيّة ليست متّفقة في كلّ تفاصيلها. تُبقي هذه البطاقة ارتباطها بصور واضحًا، مع التنبيه إلى أنّ التفاصيل تنتمي إلى تقليد سير القديسين وتحتاج إلى تمييز دقيق بين المصادر."},{"en":"Leontios of Tripoli","ar":"القديس ليونتيوس الطرابلسي","letter":"L","status":"Saint · Martyr with companions in tradition","place":"Tripoli · طرابلس، فينيقيا","years":"Ancient tradition · 1st century","storyEn":"Leontios is honoured in an ancient Christian tradition connected with Tripoli in Phoenicia. The account tells of a Roman officer who encountered Christian teaching, embraced the faith and was put to death with companions remembered as Hypatios and Theodoulos. The names and setting are preserved in martyrological traditions, but the chronology and narrative details are not equally supported by surviving historical evidence. His entry is included to represent the early Christian memory of the northern Lebanese coast, with the uncertainty made explicit.","storyAr":"يُكرَّم ليونتيوس في تقليد مسيحي قديم مرتبط بطرابلس الفينيقيّة. وتروي الرواية أنّ ضابطًا رومانيًّا تعرّف إلى التعليم المسيحي واعتنق الإيمان، ثم قُتل مع رفيقَيه اللذين يُذكران باسمَي هيباتيوس وثيودولوس. حُفظت الأسماء والمكان في تقاليد السنكسارات، لكنّ التسلسل الزمني وتفاصيل الرواية لا تستند كلّها إلى أدلّة تاريخيّة متساوية القوّة. أُدرجت سيرته لإظهار الذاكرة المسيحيّة القديمة للساحل اللبناني الشمالي، مع توضيح حدود المعلومات المتاحة."},{"en":"Hypatios of Tripoli","ar":"القديس هيباتيوس الطرابلسي","letter":"H","status":"Saint · Martyr with companions in tradition","place":"Tripoli · طرابلس، فينيقيا","years":"Ancient tradition · 1st century","storyEn":"Hypatios is named in the traditional account of the Christian martyrs associated with Leontios of Tripoli and Theodoulos. The story places their witness in Roman-era Phoenicia and remembers them as companions who shared the same commitment to Christ. Very little independent biographical information survives about Hypatios, and the account is preserved chiefly through later martyrological tradition. The website therefore records his commemoration without presenting uncertain narrative details as established fact.","storyAr":"يَرِد اسم هيباتيوس في الرواية التقليديّة لشهداء طرابلس المرتبطين بليونتيوس وثيودولوس. وتضع الرواية شهادتهم في فينيقيا في العصر الروماني، وتذكرهم رفقاء تشاركوا الثبات في الإيمان بالمسيح. لا تتوافر معلومات سيريّة مستقلّة كثيرة عن هيباتيوس، إذ حُفظت قصّته أساسًا في تقاليد السنكسارات اللاحقة. لذلك تسجّل الصفحة تذكاره من دون عرض التفاصيل غير المؤكّدة كأنّها حقائق ثابتة."},{"en":"Theodoulos of Tripoli","ar":"القديس ثيودولوس الطرابلسي","letter":"T","status":"Saint · Martyr with companions in tradition","place":"Tripoli · طرابلس، فينيقيا","years":"Ancient tradition · 1st century","storyEn":"Theodoulos is remembered alongside Leontios and Hypatios in a traditional account of early Christian witness at Tripoli. Later calendars preserve the names of the three companions, although the surviving historical record is limited and the details of the story vary. His commemoration points to the ancient Christian communities of the Phoenician coast and to the way local churches preserved the memory of believers who were understood to have suffered for their faith.","storyAr":"يُذكر ثيودولوس إلى جانب ليونتيوس وهيباتيوس في رواية تقليديّة عن الشهادة المسيحيّة الأولى في طرابلس. وقد حفظت التقاويم الكنسيّة اللاحقة أسماء الرفقاء الثلاثة، مع أنّ السجلّ التاريخي المتبقي محدود وتختلف تفاصيل القصّة بين الروايات. ويشير تذكاره إلى الجماعات المسيحيّة القديمة على الساحل الفينيقي وإلى الطريقة التي حفظت بها الكنائس المحليّة ذكرى المؤمنين الذين اعتُبروا شهداء من أجل إيمانهم."},{"en":"The 500 Martyrs of Tyre","ar":"الخمسمئة شهيد من صور","letter":"F","status":"Martyrs · Collective commemoration in tradition","place":"Tyre · صور","years":"Traditionally commemorated in 304","storyEn":"A collective Christian commemoration remembers a large group of believers from Tyre who suffered during the persecutions associated with Emperor Diocletian. Later accounts give the number as five hundred and describe the group’s death as a public act of imperial persecution. Because the surviving sources are brief and the number belongs to the traditional account, this entry treats the figure as a liturgical and historical memory rather than a verified census. Their commemoration recalls the cost borne by early Christian communities along the Phoenician coast.","storyAr":"يحفظ التقليد الكنسي تذكار جماعة كبيرة من المؤمنين في صور الذين عانوا خلال الاضطهادات المرتبطة بالإمبراطور دقلديانوس. وتذكر روايات لاحقة أنّ عددهم بلغ خمسمئة، وتصف موتهم في سياق اضطهاد علني من السلطة الرومانيّة. وبما أنّ المصادر المتبقيّة موجزة وأنّ العدد جزء من الرواية التقليديّة، تعرض الصفحة الرقم كتذكار ليتورجي وذاكرة تاريخيّة لا كإحصاء مثبت. ويذكّرنا تذكارهم بما تحمّلته الجماعات المسيحيّة الأولى على الساحل الفينيقي."},{"en":"The 350 Disciples of Saint Maron","ar":"الثلاثمئة والخمسون من تلاميذ القديس مارون","letter":"T","status":"Martyrs · Maronite historical tradition","place":"Mount Lebanon and the region · جبل لبنان والمشرق","years":"Traditionally commemorated in 517","storyEn":"Maronite historical memory preserves the account of disciples associated with Saint Maron who were killed during conflicts in the early sixth century. Later tradition gives their number as three hundred and fifty and remembers them as witnesses who remained faithful to their Church. The political and theological conflicts of that period were complex, and modern historians discuss the sources and circumstances carefully. This profile honours the community’s liturgical memory while making clear that the precise number and every detail of the traditional account are not independently certain.","storyAr":"تحفظ الذاكرة التاريخيّة المارونيّة رواية تلاميذ ارتبطوا بالقديس مارون وقُتلوا خلال صراعات مطلع القرن السادس. وتذكر التقاليد اللاحقة أنّ عددهم بلغ ثلاثمئة وخمسين، وتكرّمهم كشهود ثبتوا في أمانتهم لكنيستهم. كانت الصراعات السياسيّة واللاهوتيّة في تلك المرحلة معقّدة، ويناقش المؤرّخون المعاصرون مصادرها وظروفها بحذر. تكرّم هذه البطاقة الذاكرة الليتورجيّة للجماعة، مع توضيح أنّ العدد الدقيق وجميع تفاصيل الرواية التقليديّة ليست مؤكّدة بأدلّة مستقلّة."},{"en":"Marina the Monk","ar":"القديسة مارينا المتوحّدة","letter":"M","status":"Saint · Venerated in Eastern tradition","place":"Lebanese monastic tradition · تقليد رهباني لبناني","years":"Traditionally 5th century","storyEn":"Marina is venerated in Eastern Christian tradition through a story of devotion, humility and silence. The traditional account says she entered a monastery disguised as a man so that she could remain close to her father, who had also embraced monastic life. When she was falsely accused of fathering a child, she accepted blame without revealing her identity, and only after her death was the truth discovered. The story has circulated in several forms and is not a modern documentary biography; in Lebanon she is especially associated with monastic memory and devotion.","storyAr":"تُكرَّم مارينا في التقليد المسيحي الشرقي من خلال سيرة تتحدّث عن التفاني والتواضع والصمت. وتقول الرواية التقليديّة إنّها دخلت ديرًا متنكرة بهيئة رجل لتبقى قريبة من والدها الذي اختار الحياة الرهبانيّة أيضًا. وعندما اتُّهمت ظلمًا بأنّها أمّ طفل، قبلت الاتّهام من دون كشف هويّتها، ولم تظهر الحقيقة إلّا بعد وفاتها. انتشرت القصّة بصيغ متعدّدة، وليست سيرة توثيقيّة حديثة؛ وترتبط في لبنان بالذاكرة الرهبانيّة والإكرام الشعبي."},{"en":"Joseph of Damascus","ar":"القديس يوسف الدمشقي","letter":"J","status":"Orthodox saint · Priest and martyr","place":"Born in Beirut · بيروت; martyred in Damascus","years":"Martyred 1860","storyEn":"Joseph of Damascus was an Antiochian Orthodox priest and teacher born in Beirut. He served the Christian community in Damascus during a period of intense tension and violence in 1860. Church tradition remembers him among those killed during the Damascus persecution, on the same day associated with the Massabki brothers. His story belongs to the wider shared Christian heritage of Lebanon and Syria and is included here with his Orthodox identity clearly stated, rather than implying that he belongs to the Catholic canonisation process.","storyAr":"كان يوسف الدمشقي كاهنًا ومعلّمًا من كنيسة أنطاكية الأرثوذكسيّة، وُلد في بيروت وخدم الجماعة المسيحيّة في دمشق خلال مرحلة توتّر وعنف شديدين سنة 1860. وتكرّمه الذاكرة الكنسيّة بين الذين قُتلوا في اضطهاد دمشق، في اليوم نفسه المرتبط باستشهاد الإخوة المسابكي. تنتمي سيرته إلى التراث المسيحي المشترك بين لبنان وسوريا، لذلك أُدرج هنا مع توضيح انتمائه الأرثوذكسي، لا باعتباره جزءًا من مسار إعلان القداسة الكاثوليكي."},{"en":"Blessed Jacques Haddad (Abouna Yaacoub)","ar":"الطوباوي الأب يعقوب الحداد الكبوشي","letter":"J","status":"Blessed · Capuchin priest","place":"Ghazir · غزير","years":"1875–1954","storyEn":"Khalil Haddad, known in religious life as Father Jacques, was born in Ghazir in 1875 and became a Capuchin priest. He devoted himself to preaching, education and practical care for people who were poor, sick or abandoned. He founded the Congregation of the Franciscan Sisters of the Cross and established works of care that developed into hospitals and social services. His ministry combined public preaching with direct service: he sought out people in need and organised lasting institutions to support them. He was beatified in 2008, and is widely known in Lebanon as Abouna Yaacoub.","storyAr":"وُلد خليل الحداد، المعروف في الحياة الرهبانيّة باسم الأب يعقوب، في غزير سنة 1875، وأصبح كاهنًا كبوشيًا. كرّس حياته للكرازة والتربية والعناية العمليّة بالفقراء والمرضى والمتروكين. أسّس جمعيّة راهبات الصليب الفرنسيسكانيّات، وأقام مؤسّسات للرعاية تطوّرت إلى مستشفيات وخدمات اجتماعيّة. جمعت خدمته بين الوعظ والعمل المباشر؛ فكان يبحث عن المحتاجين وينظّم مؤسّسات دائمة لمساندتهم. أُعلن طوباويًا سنة 2008، ويُعرف في لبنان باسم الأب يعقوب."},{"en":"Elias Hoayek","ar":"الطوباوي البطريرك الياس الحويّك","letter":"E","status":"Blessed · Maronite patriarch","place":"Helta · حلتا، البترون","years":"1843–1931 · Beatified 2026","storyEn":"Elias Hoayek was born in Helta in the Batroun district in 1843 and became the 72nd Maronite Patriarch. His long patriarchate included a period of famine, war and the political upheavals surrounding the emergence of modern Lebanon. He is remembered for pastoral care during hardship, for founding the Congregation of the Maronite Sisters of the Holy Family, and for his role in advocating for the establishment of Greater Lebanon in 1920. Pope Leo XIV authorised the decree recognising a miracle attributed to his intercession in May 2026; he was beatified in Dimane on 25 July 2026. He is therefore correctly listed as Blessed, not merely Venerable.","storyAr":"وُلد الياس الحويّك في حلتا، قضاء البترون، سنة 1843، وأصبح البطريرك الماروني الثاني والسبعين. امتدّت بطريركيّته الطويلة خلال المجاعة والحرب والتحوّلات السياسيّة التي رافقت نشوء لبنان الحديث. يُذكر برعايته لأبناء الكنيسة في زمن الشدائد، وبإنشائه جمعيّة راهبات العائلة المقدّسة المارونيّات، وبدوره في المطالبة بقيام دولة لبنان الكبير سنة 1920. أذن البابا لاون الرابع عشر في أيار 2026 بإصدار مرسوم الاعتراف بأعجوبة منسوبة إلى شفاعته، وأُعلن طوباويًا في الديمان في 25 تموز 2026. لذلك يُدرج هنا بصفة طوباوي، لا مكرّم فقط."},{"en":"Antonios Tarabay","ar":"الأب أنطونيوس طربيه","letter":"A","status":"Maronite hermit priest · local veneration","place":"Tannourine & Qannoubine Valley · تنورين ووادي قاديشا","years":"1911–1998","storyEn":"Born Gabriel Tarabay in 1911, he entered the Maronite religious life and was ordained a priest in 1935. After years of ministry, he chose the hidden life of a hermit and spent decades at the Monastery of Saint Elisha in the Qadisha Valley. Accounts of his life describe a ministry of prayer, spiritual guidance and quiet hospitality to visitors who came seeking counsel. He died in 1998 and was buried near the monastery where he had lived as a hermit. He is remembered with deep local devotion; this entry does not assign him an official beatification status.","storyAr":"وُلد جبرائيل طربيه سنة 1911، ودخل الحياة الرهبانيّة المارونيّة ورُسم كاهنًا سنة 1935. وبعد سنوات من الخدمة، اختار حياة الحبساء، وأمضى عقودًا في دير مار أليشع في وادي قاديشا. وتصف الروايات حياته بأنّها كانت مكرّسة للصلاة والإرشاد الروحي واستقبال الزائرين بهدوء ومحبّة. توفّي سنة 1998 ودُفن قرب الدير الذي عاش فيه ناسكًا. يُكرَّم محليًّا بإكرام كبير؛ ولا تمنحه هذه البطاقة صفة رسميّة في مسار التطويب."},{"en":"Béchara Abou Mrad","ar":"الأب بشارة أبو مراد","letter":"B","status":"Servant of God · Cause for beatification","place":"Dahr el-Ahmar · دير الأحمر، البقاع","years":"1853–1930","storyEn":"Béchara Abou Mrad was a Melkite Greek Catholic priest associated with Dahr el-Ahmar in the Bekaa. He served parish communities through pastoral care, prayer and a reputation for personal holiness. Devotion to his memory continued after his death, and his cause has been presented in the Church’s process for beatification. The title Servant of God indicates that a cause has been opened; it does not mean that he has been beatified or canonised. His inclusion broadens the directory beyond the Maronite tradition to reflect Lebanon’s wider Eastern Catholic heritage.","storyAr":"كان بشارة أبو مراد كاهنًا من كنيسة الروم الملكيّين الكاثوليك، ارتبط اسمه بدير الأحمر في البقاع. خدم الرعايا من خلال الرعاية الكهنوتيّة والصلاة والسمعة المرتبطة بقداسة حياته. واستمرّ إكرام ذكراه بعد وفاته، وقد قُدّمت قضيّته ضمن مسار الكنيسة للتطويب. وتشير صفة خادم الله إلى افتتاح دعوى القداسة، ولا تعني أنّه أُعلن طوباويًا أو قديسًا. وتوسّع إضافته الدليل ليتجاوز التقليد الماروني ويعكس التراث الكاثوليكي الشرقي الأوسع في لبنان."}].map(entry => ({ ...entry, group: "Lebanese" })));
  entries.sort((a, b) => (a.group === b.group ? a.en.localeCompare(b.en) : a.group === "Lebanese" ? -1 : 1));
  const esc = (s) => String(s||"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
  function openSaint(s){
    panelTitle.textContent=s.en;
    output.innerHTML=`<div class="saint-detail"><button class="back-button" data-saints-back>← Back to all saints / العودة إلى اللائحة</button><p class="saint-status">${esc(s.status)} · ${esc(s.years)}</p><h3>${esc(s.en)}</h3><p class="meaning">${esc(s.place)}</p><div class="two-language"><div><div class="reference">ENGLISH</div><p>${esc(s.storyEn)}</p></div><div dir="rtl"><div class="reference">العربية</div><p class="arabic">${esc(s.storyAr)}</p></div></div><p class="meaning">Sources and further reading: <a href="https://www.vatican.va/news_services/liturgy/saints/ns_lit_doc_20040516_al-hardini_en.html" target="_blank" rel="noopener">Vatican biography of Nimatullah</a> · <a href="https://press.vatican.va/news_services/liturgy/saints/ns_lit_doc_20010610_rafqa-choboq_en.html" target="_blank" rel="noopener">Vatican biography of Rafqa</a> · <a href="https://gcatholic.org/saints/data/country-LB" target="_blank" rel="noopener">Lebanese saints and blesseds reference list</a>.</p><p class="meaning">Canonisation status is shown separately from traditional veneration. Biographies are concise summaries; dates and historical details are based on published Church biographies and reference lists.</p></div>`;
    output.querySelector("[data-saints-back]").addEventListener("click",renderSaints);
  }
  function renderSaints(){
    panelTitle.textContent="Saints from Lebanon & around the world · قدّيسو لبنان والعالم";
    const letters=[..."ABCDEFGHIJKLMNOPQRSTUVWXYZ"];
    output.innerHTML=`<p class="meaning">A growing, searchable guide to saints, blesseds and other holy figures connected with Lebanon and the Eastern Christian traditions. / دليل متجدّد للقديسين والطوباويين وشخصيّات القداسة المرتبطة بلبنان وتقاليد الكنائس الشرقيّة.</p><div class="saints-toolbar"><input class="saints-search" id="saintsSearch" type="search" placeholder="Search a name, place or status… / ابحث عن اسم أو منطقة"><select id="saintsGroup" class="saints-search" aria-label="Filter saints"><option value="Lebanese">Lebanese & Maronite first</option><option value="All">All ${entries.length} profiles</option><option value="Worldwide">Saints from around the world</option></select><div class="alphabet" id="saintsAlphabet"></div></div><div class="saints-grid" id="saintsGrid"></div><p class="meaning">This catalogue currently includes ${entries.length} entries. Lebanese and Maronite figures are prioritised; international saints are clearly identified by their place and tradition. Traditional accounts and documented biographies are distinguished.</p>`;
    let letter="";
    const alphabet=$("#saintsAlphabet");
    letters.forEach(ch=>{const b=document.createElement("button");b.textContent=ch;b.addEventListener("click",()=>{letter=letter===ch?"":ch;draw()});alphabet.appendChild(b)});
    const draw=()=>{
      const q=$("#saintsSearch").value.toLowerCase().trim();
      alphabet.querySelectorAll("button").forEach(b=>b.classList.toggle("active",b.textContent===letter));
      const group=$("#saintsGroup").value;
      const found=entries.filter(s=>(group==="All"||s.group===group)&&(!letter||s.letter===letter)&&(s.en+" "+s.ar+" "+s.place+" "+s.status).toLowerCase().includes(q));
      $("#saintsGrid").innerHTML=found.length?found.map((s,i)=>`<button class="saint-card" data-saint-index="${entries.indexOf(s)}"><span class="saint-letter">${esc(s.letter)}</span><span class="saint-status">${esc(s.status)}</span><h3>${esc(s.en)}</h3><p lang="ar" dir="rtl">${esc(s.ar)}</p><p>${esc(s.place)}</p></button>`).join(""):'<p class="meaning">No matching names. Try another spelling or letter.</p>';
      $("#saintsGrid").querySelectorAll("[data-saint-index]").forEach(b=>b.addEventListener("click",()=>openSaint(entries[Number(b.dataset.saintIndex)])));
    };
    $("#saintsSearch").addEventListener("input",draw);$("#saintsGroup").addEventListener("change",draw);draw();
  }
  function renderPriest(){
    panelTitle.textContent="Sunday worship · الحياة الكنسية";
    output.innerHTML=`<div class="saint-detail"><p class="section-kicker">THE SUNDAY LITURGY</p><h3>Gathered around the altar.</h3><p>In the Sunday Divine Liturgy, the community gathers to hear the Word, pray together and celebrate the Eucharist. The priest presides at the altar in service to the people and the Church.</p><p class="arabic" lang="ar" dir="rtl">في القداس الإلهي يوم الأحد، تجتمع الجماعة لسماع كلمة الله والصلاة معًا والاحتفال بالقربان المقدّس. ويترأس الكاهن الصلاة عند المذبح في خدمة المؤمنين والكنيسة.</p><p class="meaning">A simple guide to the parts of the Mass, the liturgical year and the people who serve in the Church will be added here.</p><button class="text-button" data-action="daily">Read today's liturgy ↗</button></div>`;
  }
  window.addEventListener("verbum:view",e=>{if(e.detail==="saints")renderSaints();if(e.detail==="priest")renderPriest()});
})();
